export type EditorAppLocale = keyof typeof editorAppCopy;
export type EditorAppCopyKey = keyof typeof editorAppCopy.en;

export function getEditorAppCopy(locale: EditorAppLocale, key: EditorAppCopyKey, values: Record<string, string | number> = {}): string {
  return editorAppCopy[locale][key].replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
}
